-- payment_plan: An arrangement to clear arrears in instalments
CREATE TABLE payment_plan (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  collection_case_id           uuid NOT NULL REFERENCES collection_case(id),
  total_amount                 numeric(28,8) NOT NULL,
  currency                     char(3) NOT NULL,
  installment_count            integer NOT NULL,
  frequency                    varchar(40) NOT NULL CHECK (frequency IN ('DAILY', 'WEEKLY', 'FORTNIGHTLY', 'MONTHLY', 'QUARTERLY', 'SEMI_ANNUAL', 'ANNUAL', 'AT_MATURITY')),
  start_date                   date NOT NULL,
  installments                 jsonb NOT NULL,
  paid_amount                  numeric(28,8) NOT NULL DEFAULT 0,
  status                       varchar(40) NOT NULL DEFAULT 'PROPOSED' CHECK (status IN ('PROPOSED', 'ACTIVE', 'COMPLETED', 'BROKEN', 'CANCELLED')),
  interest_frozen              boolean NOT NULL DEFAULT false,
  requires_approval            boolean NOT NULL DEFAULT false,
  approval_request_id          uuid,
  activated_by                 varchar(64),
  activated_at                 timestamptz,
  cancel_reason                varchar(255),
  broken_at                    timestamptz,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
