COMMENT ON COLUMN payment_plan.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN payment_plan.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN payment_plan.created_at IS 'Creation time';
