COMMENT ON COLUMN payment_plan.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_plan.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_plan.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
